    <body>
      <div class="print-shell">
        <div class="print-toolbar">
          <button type="button" onclick="window.print()">Print / Save PDF</button>
          <button type="button" onclick="window.close()">Close</button>
        </div>
        <div class="quotation-print">
          <div class="quotation-header">
            <div class="brand-head">
              ${a}
              <h2 class="company-name">${xr(e.organizationName)}</h2>
              <div class="company-contact">
                ${xr(e.organizationAddress)}<br />
                Email: ${xr(e.organizationEmail)} | Phone: ${xr(e.organizationPhone)} | GSTIN: ${xr(e.organizationGstin)}
              </div>
            </div>
            <div class="party-grid">
              <div class="party-card">
                <div class="section-label">Customer Details</div>
                <div class="field-row"><strong>Customer Name</strong><span>${xr(cn(e.companyName))}</span></div>
                <div class="field-row"><strong>Client Account No.</strong><span>${xr(cn(e.clientAccountNumber))}</span></div>
                <div class="field-row"><strong>Contact Person</strong><span>${xr(cn(e.contactPerson))}</span></div>
                <div class="field-row"><strong>Email</strong><span>${xr(cn(e.email))}</span></div>
                <div class="field-row"><strong>GSTIN</strong><span>${xr(cn(e.gstin))}</span></div>
                <div class="field-row"><strong>Address</strong><span>${xr(cn(e.clientAddressDetails))}</span></div>
              </div>
              <div class="party-card">
                <div class="section-label">Sales Details</div>
                <div class="field-row"><strong>Sales Executive</strong><span>${xr(e.accountOwner)}</span></div>
                <div class="field-row"><strong>Mobile Number</strong><span>${xr(e.organizationPhone)}</span></div>
                <div class="field-row"><strong>Email Address</strong><span>${xr(e.organizationEmail)}</span></div>
                <div class="field-row"><strong>Quotation Reference</strong><span>${xr(e.quotationNumber)}</span></div>
              </div>
            </div>
          <h1>SALES QUOTATION</h1>
          </div>
          <div class="quotation-main">
            <div class="meta-grid">
              <div class="meta-cell">
                <div class="meta-label">Quotation No.</div>
                <div class="meta-value">${xr(e.quotationNumber)}</div>
              </div>
              <div class="meta-cell">
                <div class="meta-label">Quotation Date</div>
                <div class="meta-value">${xr(e.quotationDate)}</div>
              </div>
              <div class="meta-cell">
                <div class="meta-label">Valid Until</div>
                <div class="meta-value">${xr(e.validUntil)}</div>
              </div>
              <div class="meta-cell">
                <div class="meta-label">Currency</div>
                <div class="meta-value">${xr(e.currency)}</div>
              </div>
            </div>
            <table class="items-table">
              <thead>
                <tr>
                  <th style="width:42px;">Sr.</th>
                  <th>Description</th>
                  <th style="width:50px;">Qty</th>
                  <th style="width:58px;">Unit</th>
                  <th style="width:84px;">Rate</th>
                  <th style="width:92px;">Amount</th>
                </tr>
              </thead>
              <tbody>
                ${n||'<tr><td colspan="6">No quotation items available.</td></tr>'}
              </tbody>
            </table>

            <div class="summary-layout">
              <div class="summary-card">
                <div class="section-label">Quotation Details</div>
                <div class="detail-row"><strong>Profile Name</strong><span>${xr(cn(e.profileName))}</span></div>
                <div class="detail-row"><strong>Project</strong><span>${xr(cn(e.projectName))}</span></div>
                <div class="detail-row"><strong>Account Owner</strong><span>${xr(cn(e.accountOwner))}</span></div>
                <div class="detail-row"><strong>Subject</strong><span>${xr(cn(e.quotationSubject))}</span></div>
                <div class="detail-row"><strong>Product</strong><span>${xr([e.product,e.otherProduct].filter(i=>i&&i!=="-").join(" / "))}</span></div>
                <div class="detail-row"><strong>Service</strong><span>${xr(cn(e.otherService))}</span></div>
              </div>
              <div class="totals-card">
                <div class="section-label">Amount Summary</div>
                <div class="total-row"><strong>Sub Total</strong><span>${xr(Lr(e.subtotal,e.currency))}</span></div>
                <div class="total-row"><strong>CGST</strong><span>${xr(Lr(e.cgst,e.currency))}</span></div>
                <div class="total-row"><strong>SGST</strong><span>${xr(Lr(e.sgst,e.currency))}</span></div>
                <div class="total-row"><strong>IGST</strong><span>${xr(Lr(e.igst,e.currency))}</span></div>
                <div class="total-row"><strong>Other Tax</strong><span>${xr(Lr(e.otherTax,e.currency))}</span></div>
                <div class="total-row grand-total"><strong>Total Amount</strong><span>${xr(Lr(e.total,e.currency))}</span></div>
              </div>
            </div>

            <div class="amount-words"><strong>Amount in Words</strong>${xr(e.amountInWords)}</div>

            <div class="terms-grid">
              <div class="terms-card">
                <h3 class="terms-title">Inquiry Reference</h3>
                <div class="terms-value">Number: ${xr(cn(e.customerReferenceNumber))}&#10;Date: ${xr(cn(e.customerReferenceDate))}&#10;Subject: ${xr(cn(e.customerReferenceSubject))}</div>
              </div>
              <div class="terms-card">
                <h3 class="terms-title">Terms &amp; Conditions</h3>
                <div class="terms-value">Delivery: ${xr(cn(e.deliveryTerms))}&#10;Payment: ${xr(cn(e.paymentTerms))}&#10;Warranty: ${xr(cn(e.warrantyTerms))}</div>
              </div>
              <div class="terms-card">
                <h3 class="terms-title">Quotation Notes</h3>
                <div class="terms-value">${xr(cn(e.quotationNotes))}</div>
              </div>
              <div class="terms-card">
                <h3 class="terms-title">Status</h3>
                <div class="terms-value">Status: ${xr(e.statusLabel)}${e.rejectionReason?`&#10;Reason: ${xr(e.rejectionReason)}`:""}</div>
              </div>
            </div>
          </div>
          <div class="quotation-footer">
            <strong>${xr(e.organizationName)}</strong><br />
            Website: ${xr(e.website||Xo.website)} | Email: ${xr(e.organizationEmail)} | Phone: ${xr(e.organizationPhone)}
          </div>
        </div>
      </div>
    </body>
